function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), ms));
}

async function fetchWithTimeout(url, ms) {
  let result = await Promise.race([fetchData(url), timeout(ms)]);
  return result;
}

async function sequentialFetch() {
  console.log("Sequential fetch started");
  let user = await fetchData("/api/user");
  console.log("User fetched:", user);
  let posts = await fetchData("/api/posts");
  console.log("Posts fetched:", posts);
  let comments = await fetchData("/api/comments");
  console.log("Comments fetched:", comments);
  console.log("All done sequentially!");
}

async function parallelFetch() {
  console.log("Parallel fetch started");
  [user, posts, comments] = await Promise.all([fetchData("/api/user"), fetchData("/api/posts"), fetchData("/api/comments")]);
  console.log("User:", user);
  console.log("Posts:", posts);
  console.log("Comments:", comments);
  console.log("All done in parallel!");
}

