class DataService {
  cache;
  initialized = false;
  async initialize() {
    if (this.initialized) {
      return;
    }
    console.log("Initializing DataService...");
    let config = await fetchData("/api/config");
    this.cache = await fetchData("/api/cache");
    this.initialized = true;
    console.log("DataService initialized!");
  }
  async getData(key) {
    if (!this.initialized) {
      await this.initialize();
    }
    if (this.cache[key]) {
      return this.cache[key];
    }
    let data = await fetchData("/api/data/" + key);
    this.cache[key] = data;
    return data;
  }
}

